// Generates /tmp/test20/cases.jsonl for the jsonschema behavioral corpus.
// Each case: {"id": int, "a": "<instance json string>", "b": "<schema json string>"}
const fs = require('fs');

let id = 0;
const cases = [];
function add(a, b, note) {
  id += 1;
  cases.push({ id, a: JSON.stringify(a), b: JSON.stringify(b), note: note || '' });
}

// ---------- A. type ----------
add("hello", { type: "string" }, "type string pass");
add(5, { type: "string" }, "type string fail, 1 err");
add(5, { type: "integer" }, "integer pass");
add(1.0, { type: "integer" }, "1.0 is integer in jsonschema (float with integral value)");
add(1.5, { type: "integer" }, "1.5 not integer");
add(true, { type: "number" }, "bool is NOT a number in jsonschema");
add(5, { type: "number" }, "number pass");
add(1.5, { type: "number" }, "float is number");
add(true, { type: "boolean" }, "bool pass");
add(1, { type: "boolean" }, "1 is not boolean (Python True==1 but isinstance check)");
add(null, { type: "null" }, "null pass");
add(0, { type: "null" }, "0 is not null");
add([], { type: "array" }, "array pass");
add({}, { type: "object" }, "object pass");
add(null, { type: ["string", "null"] }, "multi-type pass");
add(5, { type: ["string", "null"] }, "multi-type fail, 1 err");
add(1, { type: "bogus" }, "unknown type -> crash (TypeError in jsonschema)");
add(1, { type: ["string", 5] }, "type array with non-string -> check_schema crash");

// ---------- B. enum / const ----------
add("a", { enum: [1, "a", null] }, "enum pass");
add("b", { enum: [1, "a", null] }, "enum fail 1 err");
add(1.0, { enum: [1] }, "enum: 1.0 in [1] (Python equality)");
add(1, { enum: [true] }, "enum: 1 in [true]? Python 1==True");
add("1", { enum: [1] }, "enum: '1' not in [1]");
add(null, { enum: [false] }, "enum: null vs false");
add(0, { enum: [false] }, "enum: 0 in [false]? Python 0==False");
add(5, { const: 5 }, "const pass");
add(6, { const: 5 }, "const fail: draft4 ignores const, 6+ 1 err");
add(1, { const: true }, "const true vs 1: Python equality?");
add([1, 2], { const: [1, 2] }, "const array equality");
add({ a: 1 }, { const: { a: 1 } }, "const object equality");

// ---------- C. numeric ----------
add(4, { minimum: 5 }, "minimum fail 1 err");
add(5, { minimum: 5 }, "minimum boundary pass");
add(6, { maximum: 5 }, "maximum fail");
add(5, { maximum: 5 }, "maximum boundary pass");
add(5, { minimum: 5, exclusiveMinimum: true }, "draft4 bool exclusiveMinimum; 6+ check_schema CRASH (must be number)");
add(6, { minimum: 5, exclusiveMinimum: true }, "draft4 bool exclusiveMin pass; crash 6+ anyway");
add(5, { maximum: 5, exclusiveMaximum: true }, "draft4 bool exclusiveMaximum; crash 6+");
add(5, { exclusiveMinimum: 5 }, "numeric exclusiveMinimum fail; draft4 ignores keyword -> valid");
add(6, { exclusiveMinimum: 5 }, "numeric exclusiveMinimum pass 6+; draft4 valid too");
add(5, { exclusiveMaximum: 5 }, "numeric exclusiveMaximum fail; draft4 valid");
add(5, { exclusiveMinimum: true }, "bool exclusiveMinimum alone: draft4 valid schema; 6+ check_schema crash");
add(4, { multipleOf: 2 }, "multipleOf pass");
add(3, { multipleOf: 2 }, "multipleOf fail");
add(0.3, { multipleOf: 0.1 }, "float multipleOf: 0.3/0.1 float division quirk?");
add(3.3, { multipleOf: 1.1 }, "float multipleOf 3.3/1.1");
add(0.35, { multipleOf: 0.1 }, "float multipleOf fail case?");
add(true, { multipleOf: 2 }, "multipleOf vs bool: ignored (not number)");

// ---------- D. strings ----------
add("ab", { minLength: 3 }, "minLength fail");
add("abc", { minLength: 3 }, "minLength pass");
add("abc", { maxLength: 2 }, "maxLength fail");
add("\u{1F600}", { minLength: 1 }, "astral emoji length 1 (python) vs 2 (js)");
add("\u{1F600}\u{1F600}", { maxLength: 1 }, "2 emoji, maxLength 1: python fails, js-length would be 4");
add("é", { minLength: 2 }, "combining char e+accent = 2 code points");
add("123", { pattern: "^\\d+$" }, "pattern digits pass");
add("12a", { pattern: "^\\d+$" }, "pattern digits fail");
add("cat", { pattern: "a" }, "pattern unanchored pass");
add("abc", { pattern: "abc\\Z" }, "pythonism \\Z: matches in Python re; JS treats as literal Z");
add("abc", { pattern: "abc$" }, "$ in python matches before trailing newline too");
add("abc\n", { pattern: "abc$" }, "trailing newline: python $ matches, JS without /m does not");
add("ABC", { pattern: "^[a-z]+$" }, "pattern case fail");
add("abc", { pattern: "[a-" }, "invalid regex -> re.error crash");
add("aaa", { pattern: "^(a+)+$" }, "catastrophic backtracking candidate (short string, fine)");
add("héllo", { pattern: "^h.llo$" }, "unicode pattern dot");
add(5, { minLength: 3 }, "minLength on non-string ignored");
add(5, { pattern: "x" }, "pattern on non-string ignored");

// ---------- E. arrays ----------
add([1, 2, 3], { items: { type: "integer" } }, "items schema pass");
add([1, "a", 2.5], { items: { type: "integer" } }, "items schema: 2 errors");
add([1, "a"], { items: [{ type: "integer" }, { type: "string" }] }, "items array form pass; 2020-12 check_schema CRASH? (items must be schema)");
add(["a", 1], { items: [{ type: "integer" }, { type: "string" }] }, "items array form 2 errors; crash 2020");
add([1, "a", 3], { items: [{ type: "integer" }, { type: "string" }], additionalItems: false }, "additionalItems false; ignored in 2020");
add([1, "a", 3], { items: [{ type: "integer" }, { type: "string" }], additionalItems: true }, "additionalItems true explicit");
add([1, "a", 3], { items: [{ type: "integer" }, { type: "string" }], additionalItems: { type: "string" } }, "additionalItems schema: 1 err pre-2020");
add([1, 2, 3], { additionalItems: false }, "additionalItems without items ignored");
add(["a"], { prefixItems: [{ type: "integer" }] }, "prefixItems: only 2020 honors");
add([1, "a"], { prefixItems: [{ type: "integer" }], items: { type: "string" } }, "prefixItems+items 2020 semantics");
add([1], { minItems: 2 }, "minItems fail");
add([1, 2], { maxItems: 1 }, "maxItems fail");
add([1, 1], { uniqueItems: true }, "uniqueItems dup fail");
add([1, 1.0], { uniqueItems: true }, "uniqueItems 1 vs 1.0 -> not unique (python ==)");
add([1, true], { uniqueItems: true }, "uniqueItems 1 vs true -> ? python 1==True");
add([0, false], { uniqueItems: true }, "uniqueItems 0 vs false -> ?");
add([[1, 2], [1, 2]], { uniqueItems: true }, "uniqueItems nested arrays dup");
add([{ a: 1 }, { a: 1 }], { uniqueItems: true }, "uniqueItems objects dup");
add([1, "1"], { uniqueItems: true }, "uniqueItems 1 vs '1' unique");
add([{ a: 1, b: 2 }, { b: 2, a: 1 }], { uniqueItems: true }, "uniqueItems key order irrelevant?");
add(["a", "b"], { contains: { type: "integer" } }, "contains fail draft7+; draft4/6 ignore contains");
add([1, "b"], { contains: { type: "integer" } }, "contains pass draft7+");
add(["a", 1], { contains: { type: "string" }, minContains: 2 }, "minContains: 2019/2020 only; draft7 ignores minContains");
add([1, 2, "a"], { contains: { type: "integer" }, maxContains: 1 }, "maxContains: 2019/2020 only");
add(["a", "b", "c"], { contains: { type: "integer" } }, "contains error count = 1 regardless of item count?");
add(5, { items: { type: "integer" } }, "items on non-array ignored");
add(5, { contains: { type: "integer" } }, "contains on non-array ignored");

// ---------- F. objects ----------
add({ a: "x" }, { properties: { a: { type: "integer" } } }, "properties 1 err");
add({ a: null }, { properties: { a: { anyOf: [{ type: "integer" }, { type: "string" }] } } }, "nested anyOf: count? (1 + context?)");
add({ a: "x", b: "y" }, { properties: { a: { type: "integer" }, b: { type: "integer" } } }, "properties 2 errors");
add({ abc: "x", def: "y" }, { patternProperties: { "^a": { type: "integer" } } }, "patternProperties 1 err (abc only)");
add({ ax: 1, bx: 2 }, { patternProperties: { "x$": { type: "string" } } }, "patternProperties 2 errs");
add({ a: 1, b: 2, c: 3 }, { properties: { a: {} }, additionalProperties: false }, "additionalProperties false: 1 err or per-extra?");
add({ x: "a", y: "b" }, { additionalProperties: { type: "integer" } }, "additionalProperties schema: 2 errs");
add({ b: 1 }, { properties: { a: {} }, patternProperties: { "^b": {} }, additionalProperties: false }, "addlProps false but covered by pattern -> valid");
add({}, { required: ["a", "b", "c"] }, "required 3 missing -> 3 errors?");
add({ b: 1 }, { required: ["a"] }, "required 1 missing");
add({ a: 1 }, { minProperties: 2 }, "minProperties fail");
add({ a: 1, b: 2 }, { maxProperties: 1 }, "maxProperties fail");
add({ a: 1, abc: 2 }, { propertyNames: { minLength: 3 } }, "propertyNames 1 err; draft4/6 ignore");
add({ ab: 1, cd: 2 }, { propertyNames: { pattern: "^z" } }, "propertyNames 2 errs");
add({ a: 1 }, { dependencies: { a: ["b", "c"] } }, "dependencies array form: 1 err or 2?; 2020 ignores dependencies");
add({ a: 1, b: 2 }, { dependencies: { a: ["b"] } }, "dependencies array pass");
add({ a: 1 }, { dependencies: { a: { required: ["b"] } } }, "dependencies schema form");
add({ a: 1 }, { dependencies: { a: { properties: { b: { type: "string" } }, required: ["b"] } } }, "dependencies schema form nested");
add({ a: 1 }, { dependentRequired: { a: ["b"] } }, "dependentRequired 2019/2020 only");
add({ a: 1 }, { dependentSchemas: { a: { required: ["b"] } } }, "dependentSchemas 2019/2020 only");
add(5, { properties: { a: { type: "integer" } } }, "properties on non-object ignored");
add(5, { required: ["a"] }, "required on non-object ignored");

// ---------- G. combinators ----------
add(5, { allOf: [{ type: "integer" }, { minimum: 10 }] }, "allOf 1 branch fails -> 1 err");
add("x", { allOf: [{ type: "integer" }, { type: "string", minLength: 5 }] }, "allOf both fail -> 2 errs");
add("x", { allOf: [{ allOf: [{ type: "integer" }] }] }, "nested allOf 1 err");
add(null, { anyOf: [{ type: "integer" }, { type: "string" }] }, "anyOf 0 match: 1 err (context holds branch errs)");
add(5, { anyOf: [{ type: "integer" }, { type: "string" }] }, "anyOf 1 match pass");
add("ab", { anyOf: [{ type: "integer", minimum: 10 }, { type: "string", minLength: 3 }] }, "anyOf branches each 1 err: iter_errors count?");
add(null, { oneOf: [{ type: "integer" }, { type: "string" }] }, "oneOf 0 match -> 1 err");
add(5, { oneOf: [{ type: "integer" }, { type: "string" }] }, "oneOf 1 match pass");
add(5, { oneOf: [{ type: "integer" }, { minimum: 0 }] }, "oneOf 2 match -> 1 err");
add(5, { not: { type: "integer" } }, "not fail 1 err");
add(5, { not: {} }, "not {} always fails");
add(5, { if: { type: "integer" }, then: { minimum: 10 } }, "if/then: draft4/6 ignore -> valid; 7+ err");
add("ab", { if: { type: "integer" }, else: { minLength: 3 } }, "if/else draft7+ err");
add(5, { if: { type: "integer" } }, "if alone no-op");
add(5, { then: { minimum: 10 } }, "then without if ignored");
add(5, { if: { type: "string" }, then: { minimum: 10 } }, "if not matching, no else -> valid");
add(1, { foo: "bar" }, "unknown keyword ignored all drafts");
add("x", { allOf: [{ type: "string" }, { anyOf: [{ minLength: 5 }, { pattern: "^z" }] }] }, "deep nest: allOf->anyOf error count");

// ---------- H. $ref ----------
add("a", { definitions: { x: { type: "integer" } }, $ref: "#/definitions/x" }, "local ref definitions");
add("a", { $defs: { x: { type: "integer" } }, $ref: "#/$defs/x" }, "local ref $defs (pointer works in all drafts?)");
add({ child: { child: "x" } }, { type: "object", properties: { child: { $ref: "#" } } }, "recursive ref # pass");
add({ child: { child: "x" } }, { type: "object", properties: { child: { $ref: "#" } }, required: ["nope"] }, "recursive ref: root required fails at each level?");
add(5, { definitions: { x: { type: "integer" } }, $ref: "#/definitions/x", minimum: 10 }, "$ref siblings: 4-7 ignore, 2019/2020 evaluate");
add("a", { definitions: { x: { type: "integer" } }, $ref: "#/definitions/x", minimum: 10 }, "$ref siblings: type err everywhere, minimum only 19/20");
add("a", { definitions: { x: { $ref: "#/definitions/y" }, y: { type: "integer" } }, $ref: "#/definitions/x" }, "nested chained refs");
add(1, { $ref: "#/definitions/nope" }, "ref to missing pointer -> crash?");
add(1, { $ref: "http://example.com/schema.json" }, "remote ref -> resolution error crash?");
add(1, { $ref: "#" }, "self ref infinite recursion -> crash?");

// ---------- I. $schema / validator_for ----------
add(1, { $schema: "http://json-schema.org/draft-04/schema#" }, "validator_for draft4 with #");
add(1, { $schema: "http://json-schema.org/draft-04/schema" }, "validator_for draft4 no #");
add(1, { $schema: "http://json-schema.org/draft-06/schema#" }, "validator_for draft6 #");
add(1, { $schema: "http://json-schema.org/draft-06/schema" }, "validator_for draft6 no #");
add(1, { $schema: "http://json-schema.org/draft-07/schema#" }, "validator_for draft7 #");
add(1, { $schema: "http://json-schema.org/draft-07/schema" }, "validator_for draft7 no #");
add(1, { $schema: "https://json-schema.org/draft/2019-09/schema" }, "validator_for 2019 no #");
add(1, { $schema: "https://json-schema.org/draft/2019-09/schema#" }, "validator_for 2019 with #");
add(1, { $schema: "https://json-schema.org/draft/2020-12/schema" }, "validator_for 2020 no #");
add(1, { $schema: "https://json-schema.org/draft/2020-12/schema#" }, "validator_for 2020 with #");
add(1, { $schema: "http://example.com/unknown-schema#" }, "unknown $schema -> latest? warning");
add(1, { $schema: 123 }, "non-string $schema -> ?");
add("x", { $schema: "http://json-schema.org/draft-07/schema#", type: "integer" }, "draft7 $schema with type fail");

// ---------- J. boolean subschemas ----------
add({ a: 1 }, { properties: { a: true } }, "boolean subschema true");
add({ a: 1 }, { properties: { a: false } }, "boolean subschema false -> err");
add({ a: 1 }, { additionalProperties: false, properties: { a: true } }, "bool subschema + addlProps false");
add([1, 2], { items: true }, "items true");
add([1, 2], { items: false }, "items false -> err per item? 2020 items=false: err");
add(5, { not: true }, "not true -> always err");
add(5, { not: false }, "not false -> always valid");
add(5, { allOf: [true, false] }, "bool branches in allOf");
add(1, true, "boolean ROOT schema -> known crash");
add(1, false, "boolean ROOT schema false -> known crash");

// ---------- K. check_schema crash probes ----------
add(1, { type: 123 }, "check_schema crash all drafts");
add(1, { properties: [{ a: 1 }] }, "properties as array -> crash");
add(1, { minimum: "x" }, "minimum string -> crash");
add(1, { required: "a" }, "required string -> crash");
add(1, { items: 5 }, "items number -> crash");
add(1, { minLength: -1 }, "minLength negative -> crash");
add(1, { multipleOf: 0 }, "multipleOf 0 -> crash");
add(1, { enum: [] }, "empty enum: meta-schema minItems? per-draft?");
add(1, { required: [] }, "empty required: draft4 meta minItems 1? later drafts allow");
add(1, { properties: { a: { type: "integerr" } } }, "unknown type in subschema -> crash at validation?");
add(1, { patternProperties: { "[": {} } }, "invalid regex in patternProperties key -> check_schema crash?");

// ---------- L. edge ----------
add(5, {}, "empty schema");
add(null, {}, "null instance empty schema");
add([], { minItems: 0 }, "empty array");
add({}, { minProperties: 0 }, "empty object");
add("", { type: "string", minLength: 0 }, "empty string");
add(0, { minimum: 0 }, "zero");
add(-0.0, { minimum: 0 }, "negative zero");
add({ a: { a: { a: { a: { a: 5 } } } } }, { properties: { a: { properties: { a: { properties: { a: { properties: { a: { properties: { a: { type: "integer" } } } } } } } } } } }, "deep nesting pass");
add({ a: { a: { a: { a: { a: "x" } } } } }, { properties: { a: { properties: { a: { properties: { a: { properties: { a: { properties: { a: { type: "integer" } } } } } } } } } } }, "deep nesting fail 1 err");
add(12345678901234567890, { maximum: 5 }, "large integer (>2^53)");
add(1e308, { maximum: 1e300 }, "1e308 vs 1e300");
add(1e400, { minimum: 0 }, "1e400 -> json inf? python json parses to inf");
add(9007199254740993, { const: 9007199254740993 }, "big int const (python exact, js loses precision)");
add([1, [2, [3, [4, [5]]]]], { items: {} }, "ragged nested array");
add("tab\there", { pattern: "\t" }, "pattern with tab escape");

fs.writeFileSync(
  '/tmp/test20/cases.jsonl',
  cases.map(c => JSON.stringify({ id: c.id, a: c.a, b: c.b })).join('\n') + '\n'
);
fs.writeFileSync(
  '/tmp/test20/cases_annotated.jsonl',
  cases.map(c => JSON.stringify(c)).join('\n') + '\n'
);
console.log('wrote', cases.length, 'cases');

// Runs every case in /tmp/test20/cases.jsonl against the executable.
// Writes /tmp/test20/expected/<id>.out  (stdout + final "EXIT=<code>" line)
// and    /tmp/test20/expected/<id>.err  (stderr, kept for crash analysis)
const fs = require('fs');
const { spawnSync } = require('child_process');

const EXE = '/workspace/dataset/test20_executable';
const lines = fs.readFileSync('/tmp/test20/cases.jsonl', 'utf8').trim().split('\n');
let done = 0, crashed = 0;
const summary = [];
for (const line of lines) {
  const c = JSON.parse(line);
  const r = spawnSync(EXE, ['--a', c.a, '--b', c.b], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  const code = r.status === null ? `SIGNAL:${r.signal}` : String(r.status);
  let out = r.stdout || '';
  out += `EXIT=${code}\n`;
  fs.writeFileSync(`/tmp/test20/expected/${c.id}.out`, out);
  fs.writeFileSync(`/tmp/test20/expected/${c.id}.err`, r.stderr || '');
  if (r.status !== 0) crashed++;
  summary.push(`${c.id}\t${code}\t${(r.stdout || '').split('\n').filter(Boolean).length}`);
  done++;
}
fs.writeFileSync('/tmp/test20/run_summary.tsv', summary.join('\n') + '\n');
console.log(`ran ${done} cases, ${crashed} non-zero exits`);

