for(const c of cases){const out=fs.readFileSync(`expected/${c.id}.out`,"utf8");const lines=out.trim().split("\n");const exit=lines.pop();
const short=lines.length?`${lines.slice(0,5).join(",")} | errs:${lines.slice(5,10).join(",")} | chk:${lines.slice(10,15).join(",")} | tree:${lines[15]} | vf:${lines[17]} | ev:${lines[18]},${lines[19]}`:"<EMPTY STDOUT>";
console.log(`${c.id}\t${exit}\t${c.note}\t=> ${short}`);}' > analysis.txt; wc -l analysis.txt

